def scope_existing_keys(apps, schema_editor):
    """Keys issued before scoped tokens get the Full agent preset rather than no tool-level limit.

    Nothing has launched yet, so no agent relies on approvals or settings writes through an old key. The request
    budget is held to the organization's plan allowance at request time, whatever is stored here.
    """
    ApiKey = apps.get_model("api_keys", "ApiKey")
    ApiKey.objects.filter(capabilities__isnull=True).update(**FULL_AGENT)


